INSERT INTO creature_text (CreatureID,GroupID,ID,Text,Type,Language,Probability,Emote,Duration,Sound,SoundPlayType,BroadcastTextId,TextRange,comment) VALUES (236610,8,0,'This riddle must be the key to getting us out of here.',12,0,100,0,0,300091,0,287411,0,'retail quote (86644)');
INSERT INTO creature_text (CreatureID,GroupID,ID,Text,Type,Language,Probability,Emote,Duration,Sound,SoundPlayType,BroadcastTextId,TextRange,comment) VALUES (236610,9,0,'I''d heard this land belonged to the Amani, long ago. I hadn''t really thought about it beyond recorded history.',12,0,100,0,0,300095,0,298405,0,'retail quote (86644)');
INSERT INTO creature_text (CreatureID,GroupID,ID,Text,Type,Language,Probability,Emote,Duration,Sound,SoundPlayType,BroadcastTextId,TextRange,comment) VALUES (236610,10,0,'But these ancient bones--there must be generations of Amani buried here. Resting where no one can reach them.',12,0,100,0,0,300096,0,298406,0,'retail quote (86644)');
INSERT INTO creature_text (CreatureID,GroupID,ID,Text,Type,Language,Probability,Emote,Duration,Sound,SoundPlayType,BroadcastTextId,TextRange,comment) VALUES (236610,11,0,'We elves do not revere our ancestors as the orcs do, but we still honor our dead.',12,0,100,0,0,300097,0,298407,0,'retail quote (86644)');
INSERT INTO creature_text (CreatureID,GroupID,ID,Text,Type,Language,Probability,Emote,Duration,Sound,SoundPlayType,BroadcastTextId,TextRange,comment) VALUES (236610,12,0,'The Amani cannot even do that much. We''ve taken it away from them. Little wonder they hold such hatred for elvenkind.',12,0,100,0,0,300098,0,298408,0,'retail quote (86644)');
INSERT INTO creature_text (CreatureID,GroupID,ID,Text,Type,Language,Probability,Emote,Duration,Sound,SoundPlayType,BroadcastTextId,TextRange,comment) VALUES (236610,13,0,'We should get moving.',12,0,100,0,0,300099,0,298409,0,'retail quote (86644)');
